def route(word_en: str, ru: str):
    """Возвращает (level, topic-file) или None."""
    text = (word_en + ' ' + ru).lower()
    for level, fname, keys in TOPICS:
        for k in keys.split():
            if k in text:
                return level, fname
    return None
